typedef struct _otp_link_AgnssInfoRequest {
    char dummy_field;
} otp_link_AgnssInfoRequest;

typedef struct _otp_link_PhoneMsg {
    uint32_t req;
    pb_size_t which_body;
    union {
        otp_link_Hello hello;
        otp_link_Unpair unpair;
        otp_link_GetSettings get_settings;
        otp_link_Settings set_settings; /* only the fields present are changed */
        otp_link_LiveSubscribe live_subscribe;
        otp_link_StopwatchCommand stopwatch;
        otp_link_UploadBegin upload_begin;
        otp_link_Chunk chunk;
        otp_link_UploadEnd upload_end;
        otp_link_DownloadRequest download;
        otp_link_TransferAck transfer_ack;
        otp_link_TransferCancel transfer_cancel;
        otp_link_ListRequest list;
        otp_link_DeleteRequest delete_file;
        otp_link_PhoneLocation location;
        otp_link_RouteManeuvers maneuvers;
        otp_link_RouteFinish route_finish;
        otp_link_SensorCommand sensors;
        otp_link_GetMapLayers get_map_layers;
        otp_link_MapLayers set_map_layers;
        otp_link_GetDash get_dash;
        otp_link_DashConfig set_dash;
        otp_link_MediaMeta media_meta;
        otp_link_MediaClear media_clear;
        otp_link_MediaCommand media_command;
        otp_link_WorkoutCommand workout;
        otp_link_MeshCommand mesh;
        otp_link_AgnssInfoRequest agnss_info;
    } body;
} otp_link_PhoneMsg;

typedef struct _otp_link_AgnssInfo {
    otp_link_GnssModule module;
    bool fix;
} otp_link_AgnssInfo;

typedef struct _otp_link_DeviceMsg {
    uint32_t req;
    pb_size_t which_body;
    union {
        otp_link_DeviceHello hello;
        otp_link_Result result;
        otp_link_Settings settings; /* reply to GetSettings / SetSettings, and pushed on a device-side edit */
        otp_link_LiveFrame live;
        otp_link_UploadReady upload_ready;
        otp_link_Chunk chunk;
        otp_link_DownloadBegin download_begin;
        otp_link_TransferAck transfer_ack;
        otp_link_TransferCancel transfer_cancel;
        otp_link_TransferDone transfer_done;
        otp_link_FileList file_list;
        otp_link_MapCoverageList map_coverage;
        otp_link_TileList tile_list;
        otp_link_SensorList sensor_list;
        otp_link_MapLayers map_layers; /* reply to Get/Set, and pushed on a device-side edit */
        otp_link_DashConfig dash; /* reply to Get/Set (the applied layout), and pushed on a device-side edit */
        otp_link_MediaTrack media_track; /* AMS track, after Hello and on every change */
        otp_link_MediaCommand media_command; /* device button pressed and no AMS: phone should act */
        otp_link_WorkoutStatus workout_status; /* reply to STATUS, pushed on change and 1 Hz while running */
        otp_link_MeshState mesh_state;
        otp_link_MeshHistory mesh_history;
        otp_link_MeshNodes mesh_nodes;
        otp_link_MeshStats mesh_stats;
        otp_link_MeshPresets mesh_presets;
        otp_link_MeshChannels mesh_channels;
        otp_link_MeshRegions mesh_regions;
        otp_link_MeshChanged mesh_changed; /* something changed: ask again */
        otp_link_MeshQueued mesh_queued; /* reply to a send */
        otp_link_AgnssInfo agnss_info;
    } body;
} otp_link_DeviceMsg;


